elseif pc == 55 then
wu(M, band(EDI) - 7245824, 0)
wu(M, band(EDX + 8) - 7245824, ECX)
EDI = ru(M, ESP - 7245824); ESP = ESP + 4
wu(M, band(ECX + 12) - 7245824, EAX)
ESI = ru(M, ESP - 7245824); ESP = ESP + 4
wu(M, band(EAX + 4) - 7245824, ECX)
ESP = ESP + 8
do return end
elseif pc == 56 then
wu(M, band(EDX + 12) - 7245824, ECX)
wu(M, band(ECX + 12) - 7245824, EAX)
wu(M, band(EAX + 4) - 7245824, ECX)
pc = 57
elseif pc == 57 then
wu(M, band(EDI) - 7245824, 0)
EDI = ru(M, ESP - 7245824); ESP = ESP + 4
ESI = ru(M, ESP - 7245824); ESP = ESP + 4
ESP = ESP + 8
do return end
end
end
end

-- registers are per module: calls between modules go through the shared register file ctx.R
local R = ctx.R
local function LOAD() EAX, EBX, ECX, EDX, ESI, EDI, EBP, ESP, FT, FSW = R[1], R[2], R[3], R[4], R[5], R[6], R[7], R[8], R[9], R[10] end
local function SAVE() R[1], R[2], R[3], R[4], R[5], R[6], R[7], R[8], R[9], R[10] = EAX, EBX, ECX, EDX, ESI, EDI, EBP, ESP, FT, FSW end
for a, f in pairs(XF) do
	ctx.XF[a] = function() LOAD(); f(); SAVE() end
end
setmetatable(XF, {__index = function(t, a)
	local g = ctx.XF[a]
	if not g then error(string.format("NR2003 track: call to unknown %08x", a)) end
	local s = function() SAVE(); g(); LOAD() end
	t[a] = s
	return s
end})
end

